<?= $this->section('content') ?>
<div class="d-flex justify-content-between align-items-center mb-3">
  <div><h4 class="mb-1">Sale History</h4><div class="small text-muted">Search, review, export and manage sales.</div></div>
  <a href="<?=site_url('sales')?>" class="btn btn-primary"><i class="bi bi-cart-plus me-1"></i>New Sale</a>
</div>

<div id="saleHistoryPanel">
  <div class="card mb-2"><div class="card-body py-2"><div class="row g-2 align-items-end">
    <div class="col-md-2"><label class="form-label">From Date</label><input type="date" id="historyFrom" class="form-control" value="<?=date('Y-m-d')?>"></div>
    <div class="col-md-2"><label class="form-label">To Date</label><input type="date" id="historyTo" class="form-control" value="<?=date('Y-m-d')?>"></div>
    <div class="col-md-2"><label class="form-label">Sale No.</label><input type="text" id="historySaleNo" class="form-control" placeholder="Sale number"></div>
    <div class="col-md-2"><label class="form-label">Customer</label><input type="text" id="historyCustomer" class="form-control" placeholder="Name / code"></div>
    <div class="col-md-2"><label class="form-label">Transaction Type</label><select id="historyType" class="form-select"><option value="">All Types</option><option value="gas_sale">Gas Sale</option><option value="cylinder_sale">Cylinder Sale</option><option value="security_deposit">Security Deposit</option><option value="cylinder_return">Cylinder Return</option><option value="refill_service">Refill Service</option><option value="cylinder_exchange">Cylinder Exchange</option><option value="filled_cylinder">Filled Cylinder</option><option value="empty_sale">Empty Cylinder</option><option value="mixed">Mixed</option></select></div>
    <div class="col-md-2"><label class="form-label">Status</label><select id="historyStatus" class="form-select"><option value="">All</option><option value="posted">Posted</option><option value="voided">Void</option></select></div>
    <div class="col-12 d-flex justify-content-between align-items-center mt-1"><div class="d-flex gap-2"><button type="button" class="btn btn-sm btn-primary" id="historySearch">Search</button><button type="button" class="btn btn-sm btn-outline-secondary" id="historyAll">All History</button><button type="button" class="btn btn-sm btn-outline-success" id="historyExport">Export CSV</button></div><span class="small text-muted" id="historyCount"></span></div>
  </div></div></div>
  <div class="card"><div class="table-responsive"><table class="table table-sm table-hover align-middle mb-0"><thead><tr>
    <th>Sale No.</th><th>Date / Time</th><th>Customer</th><th>Type</th><th class="text-end">Subtotal</th><th class="text-end">Discount</th><th class="text-end">Current Sale</th><th class="text-end">Previous OS</th><th class="text-end">Receipt</th><th class="text-end">Net Receivable</th><th class="text-end">OS Balance</th><th>Status</th><th>User</th><th class="text-end">Action</th>
  </tr></thead><tbody id="saleHistoryBody"><tr><td colspan="14" class="text-center text-muted py-4">Loading...</td></tr></tbody></table></div></div>
</div>

<div class="modal fade" id="saleDetailsModal" tabindex="-1">
  <div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content">
    <div class="modal-header"><h5 class="modal-title">Sale Details</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
    <div class="modal-body" id="saleDetailsBody"></div>
  </div></div>
</div>

<script>
const canVoidSales=<?=json_encode($canVoidSales??false)?>;
const historyBody=document.getElementById('saleHistoryBody');
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}

document.addEventListener('wheel',e=>{if(document.activeElement?.matches('input[type="number"]'))e.preventDefault();},{passive:false});
const historyTypeLabel=t=>({gas_sale:'Gas Sale',cylinder_sale:'Cylinder Sale',security_deposit:'Security Deposit',cylinder_return:'Cylinder Return',refill_service:'Refill Service',cylinder_exchange:'Cylinder Exchange',filled_cylinder:'Filled Cylinder',empty_sale:'Empty Cylinder',mixed:'Mixed'}[t]||t||'-');
function historyQuery(){const p=new URLSearchParams({from:document.getElementById('historyFrom').value,to:document.getElementById('historyTo').value,sale_no:document.getElementById('historySaleNo').value,customer:document.getElementById('historyCustomer').value,transaction_type:document.getElementById('historyType').value,status:document.getElementById('historyStatus').value});return p.toString();}
function csvCell(v){const s=String(v??'');return '"'+s.replace(/"/g,'""')+'"';}
function exportSaleHistory(){const rows=[...historyBody.querySelectorAll('tr.sale-history-row')];if(!rows.length){alert('There are no sales to export for the current filters.');return;}const headers=['Sale No.','Date / Time','Customer','Type','Subtotal','Discount','Current Sale','Previous OS','Receipt','Net Receivable','OS Balance','Status','User'];const data=rows.map(row=>[...row.querySelectorAll('td')].slice(0,13).map(td=>td.innerText.replace(/\s+/g,' ').trim()));const csv=[headers,...data].map(r=>r.map(csvCell).join(',')).join('\r\n');const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');const from=document.getElementById('historyFrom').value||'all';const to=document.getElementById('historyTo').value||'all';a.href=url;a.download='sale-history-'+from+'-to-'+to+'.csv';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);}
async function loadSaleHistory(){historyBody.innerHTML='<tr><td colspan="14" class="text-center text-muted py-4">Loading...</td></tr>';try{const res=await fetch('<?=site_url('sales/history/data')?>?'+historyQuery(),{headers:{Accept:'application/json'}});const d=await res.json();if(!res.ok)throw new Error(d.error||'Unable to load sale history.');const rows=d.sales||[];document.getElementById('historyCount').textContent=rows.length+' sale(s)';if(!rows.length){historyBody.innerHTML='<tr><td colspan="14" class="text-center text-muted py-4">No sales found.</td></tr>';return;}historyBody.innerHTML=rows.map(s=>{const received=Number(s.receipt_amount??(Number(s.total_amount||0)-Number(s.credit_amount||0)));const st=s.status==='voided'?'<span class="badge text-bg-danger">VOID</span>':'<span class="badge text-bg-success">POSTED</span>';const action=canVoidSales&&s.status==='posted'?'<button type="button" class="btn btn-sm btn-outline-danger void-sale" data-id="'+s.id+'" data-no="'+escapeHtml(s.sale_no)+'">Delete</button>':'';return '<tr class="sale-history-row" data-id="'+s.id+'" style="cursor:pointer"><td class="fw-semibold">'+escapeHtml(s.sale_no)+'</td><td>'+escapeHtml(s.transaction_at||'')+'</td><td>'+escapeHtml(s.customer_name||'Walk-in / Cash')+'</td><td>'+escapeHtml(historyTypeLabel(s.transaction_type))+'</td><td class="text-end">'+fmtMoney(s.subtotal)+'</td><td class="text-end">'+fmtMoney(s.discount_amount)+'</td><td class="text-end">'+fmtMoney(s.total_amount)+'</td><td class="text-end">'+fmtMoney(s.previous_os_balance)+'</td><td class="text-end">'+fmtMoney(received)+'</td><td class="text-end">'+fmtMoney(s.net_receivable_amount??s.total_amount??0)+'</td><td class="text-end">'+fmtMoney(s.os_balance??s.credit_amount??0)+'</td><td>'+st+'</td><td>'+escapeHtml(s.created_by_name||'-')+'</td><td class="text-end">'+action+'</td></tr>';}).join('');historyBody.querySelectorAll('.sale-history-row').forEach(row=>row.addEventListener('click',e=>{if(!e.target.closest('.void-sale'))showSaleDetails(Number(row.dataset.id));}));historyBody.querySelectorAll('.void-sale').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();voidSale(Number(b.dataset.id),b.dataset.no);}));}catch(e){historyBody.innerHTML='<tr><td colspan="14" class="text-center text-danger py-4">'+escapeHtml(e.message)+'</td></tr>';}}
async function showSaleDetails(id){const body=document.getElementById('saleDetailsBody');body.innerHTML='<div class="text-center py-4">Loading...</div>';new bootstrap.Modal(document.getElementById('saleDetailsModal')).show();try{const res=await fetch('<?=site_url('sales/details')?>/'+id,{headers:{Accept:'application/json'}});const d=await res.json();if(!res.ok)throw new Error(d.error||'Unable to load sale details.');const s=d.sale,ms=d.movements||[];const received=Number(s.receipt_amount??(Number(s.total_amount||0)-Number(s.credit_amount||0)));const items=(d.items||[]).map(i=>{const src=ms.find(m=>Number(m.source_line_id)===Number(i.id)&&m.inventory_type==='gas_kg'&&m.direction==='out');const rateLabel=s.transaction_type==='cylinder_sale'?(i.line_type==='filled_cylinder'?'Gas '+fmtMoney(i.gas_rate)+' / Cyl '+fmtMoney(i.cylinder_price):'Cyl '+fmtMoney(i.cylinder_price)):fmtMoney(i.applied_rate);return '<tr><td>'+i.line_no+'</td><td>'+escapeHtml(i.cylinder_code||'-')+' — '+escapeHtml(i.cylinder_name||'-')+'</td><td>'+escapeHtml(i.line_type||'-')+'</td><td>'+escapeHtml(src?.unit_code||i.customer_unit_code||'-')+'</td><td class="text-end">'+Number(i.quantity||0).toFixed(3)+'</td><td class="text-end">'+Number(i.gas_weight_kg||0).toFixed(3)+'</td><td class="text-end">'+rateLabel+'</td><td class="text-end">'+fmtMoney(i.line_total)+'</td></tr>';}).join('');const paymentTypeLabel=t=>({sale:'Sale',security_deposit:'Security Deposit',security_deposit_refund:'Security Deposit Refund'}[t]||t||'-');const pays=(d.payments||[]).map(p=>'<tr><td>'+escapeHtml(paymentTypeLabel(p.payment_type))+'</td><td>'+escapeHtml(p.payment_mode||'')+'</td><td class="text-end">'+fmtMoney(p.amount)+'</td><td>'+escapeHtml(p.reference_no||'-')+'</td></tr>').join('');const movs=ms.map(m=>'<tr><td>'+escapeHtml(m.unit_code||'-')+'</td><td>'+escapeHtml(m.inventory_type||'')+'</td><td>'+escapeHtml(m.direction||'')+'</td><td class="text-end">'+Number(m.quantity||0).toFixed(3)+'</td><td>'+escapeHtml(m.source_type||'')+'</td><td>'+escapeHtml(m.notes||'')+'</td></tr>').join('');const voidInfo=s.status==='voided'?'<div class="alert alert-danger py-2"><strong>VOID</strong> — '+escapeHtml(s.voided_at||'')+' by '+escapeHtml(s.voided_by_name||'-')+'<br>Reason: '+escapeHtml(s.void_reason||'-')+'</div>':'';body.innerHTML=voidInfo+'<div class="row g-2 mb-3"><div class="col-md-3"><strong>Sale No.</strong><br>'+escapeHtml(s.sale_no)+'</div><div class="col-md-3"><strong>Date / Time</strong><br>'+escapeHtml(s.transaction_at)+'</div><div class="col-md-3"><strong>Customer</strong><br>'+escapeHtml(s.customer_name||'Walk-in / Cash')+'</div><div class="col-md-3"><strong>Type</strong><br>'+escapeHtml(historyTypeLabel(s.transaction_type))+'</div></div><div class="row g-2 mb-3"><div class="col-md-3">Previous OS Balance<br><strong>'+fmtMoney(s.previous_os_balance)+'</strong></div><div class="col-md-3">Subtotal<br><strong>'+fmtMoney(s.subtotal)+'</strong></div><div class="col-md-3">Discount<br><strong>'+fmtMoney(s.discount_amount)+'</strong></div><div class="col-md-3">Current Sale<br><strong>'+fmtMoney(s.total_amount)+'</strong></div></div><div class="row g-2 mb-3"><div class="col-md-3">Net Receivable<br><strong>'+fmtMoney(s.net_receivable_amount??s.total_amount??0)+'</strong></div><div class="col-md-3">Receipt Amount<br><strong>'+fmtMoney(received)+'</strong></div><div class="col-md-3">OS Balance<br><strong>'+fmtMoney(s.os_balance??s.credit_amount??0)+'</strong></div><div class="col-md-3">Credit / OS (legacy)<br><strong>'+fmtMoney(s.credit_amount)+'</strong></div></div><h6>Sale Lines</h6><div class="table-responsive"><table class="table table-sm"><thead><tr><th>#</th><th>Cylinder Type</th><th>Line Type</th><th>Physical / Customer Cylinder</th><th>Qty</th><th>Gas KG</th><th>Rate</th><th>Amount</th></tr></thead><tbody>'+items+'</tbody></table></div><h6 class="mt-3">Payments</h6><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Payment For</th><th>Mode</th><th class="text-end">Amount</th><th>Reference</th></tr></thead><tbody>'+pays+'</tbody></table></div><h6 class="mt-3">Inventory / Reversal Movements</h6><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Physical Cylinder</th><th>Inventory</th><th>Direction</th><th>Qty</th><th>Source</th><th>Notes</th></tr></thead><tbody>'+movs+'</tbody></table></div>';}catch(e){body.innerHTML='<div class="alert alert-danger">'+escapeHtml(e.message)+'</div>';}}
function voidSale(id,no){if(!canVoidSales)return;if(!confirm('Void sale '+no+'? Stock, cash and customer ledger effects will be reversed. The original sale will remain as VOID.'))return;const reason=prompt('Enter void reason for '+no+':','');if(reason===null)return;if(!reason.trim()){alert('Void reason is required.');return;}const f=document.createElement('form');f.method='post';f.action='<?=site_url('sales/void')?>/'+id;const c=document.createElement('input');c.type='hidden';c.name='<?=csrf_token()?>';c.value='<?=csrf_hash()?>';f.appendChild(c);const x=document.createElement('input');x.type='hidden';x.name='void_reason';x.value=reason.trim();f.appendChild(x);document.body.appendChild(f);f.submit();}

document.getElementById('historySearch').onclick=loadSaleHistory;
document.getElementById('historyAll').onclick=()=>{document.getElementById('historyFrom').value='2000-01-01';document.getElementById('historyTo').value=new Date().toISOString().slice(0,10);loadSaleHistory();};
document.getElementById('historyExport').onclick=exportSaleHistory;
loadSaleHistory();
</script>
<?= $this->endSection() ?>